import { Context, Router, SniceElement, context, element, html, property, render, state } from 'snice';
import { page } from '../router';
import 'snice/components/table/snice-table';
import 'snice/components/input/snice-input';

export const { initialize, navigate } = Router({
  target: '#app',
  type: 'hash',
  context: { user: null }
});

@page({ tag: 'users-page', routes: ['/users'] })
@element('users-page')
class UsersPage extends SniceElement {
  @property() heading = 'Users';
  @state() rows = [{ id: '1', name: 'Ada' }];
  columns = [{ key: 'name', label: 'Name' }];

  @context()
  handleContext(ctx: Context) {
    void ctx.application;
  }

  @render()
  template() {
    return html`<snice-input @input-input=${this.handleInput}></snice-input>
      <snice-table .columns=${this.columns} .data=${this.rows} @row-click=${this.handleRow}></snice-table>`;
  }

  handleInput(event: CustomEvent<{ value: string }>) {
    console.log(event.detail.value);
  }

  handleRow(event: CustomEvent<{ data: unknown }>) {
    console.log(event.detail.data);
  }
}

import 'snice/components/input/snice-input';
import 'snice/components/table/snice-table';
import { Input, Route, SniceRouter, Table } from 'snice/react';

function Dashboard() {
  return <><Input onInputChange={(event) => console.log(event.detail.value)} /><Table data={[]} columns={[]} /></>;
}

export const App = () => <SniceRouter mode="hash"><Route path="/" page={Dashboard} /></SniceRouter>;

import { Button, Table } from 'snice/react';
export function Report({ rows }) {
  return <><Button variant="primary" outline>Export</Button><Table data={rows} columns={[{ key: 'name', label: 'Name', renderCell: (value) => String(value) }]} /></>;
}

@element('responsive-panel')
class ResponsivePanel extends HTMLElement {
  @observe('resize', '.panel') resized(entries: ResizeObserverEntry[]) {}
  @render() template() { return html`<section class="panel">${this.content}</section>`; }
}

import type { SniceInput } from 'snice/components/input/snice-input.types';
import 'snice/components/button/snice-button';
@controller('search')
class SearchController {
  input!: SniceInput;
}
